#!/usr/bin/env python3
"""TokenGuard - LLM API 429 Prevention Engine

A pure-Python utility for tracking LLM API token quotas and preventing 429 errors.
Zero external dependencies - CJK-aware token estimation without tiktoken.
"""

import argparse
import json
import re
import sys
import time
from dataclasses import dataclass, field, asdict
from typing import Optional, Dict, Any

# Default model quotas (TPM = Tokens Per Minute)
DEFAULT_QUOTAS = {
    "gemini-3-flash": 1_000_000,
    "gemini-3-pro": 2_000_000,
    "claude-haiku": 50_000,
    "claude-sonnet": 200_000,
    "claude-opus": 200_000,
    "gpt-4o": 800_000,
    "deepseek": 1_000_000,
}

THROTTLE_WARNING_THRESHOLD = 0.80
THROTTLE_BLOCK_THRESHOLD = 0.95


@dataclass
class TokenUsage:
    model: str
    tpm_limit: int
    used_this_minute: int = 0
    timestamp: float = field(default_factory=time.time)

    @property
    def remaining(self) -> int:
        return max(0, self.tpm_limit - self.used_this_minute)

    @property
    def usage_pct(self) -> float:
        if self.tpm_limit == 0:
            return 100.0
        return (self.used_this_minute / self.tpm_limit) * 100

    @property
    def status(self) -> str:
        if self.usage_pct >= THROTTLE_BLOCK_THRESHOLD:
            return "BLOCKED"
        elif self.usage_pct >= THROTTLE_WARNING_THRESHOLD:
            return "THROTTLE"
        return "OK"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "tpm_limit": self.tpm_limit,
            "used_this_minute": self.used_this_minute,
            "remaining": self.remaining,
            "usage_pct": f"{self.usage_pct:.1f}%",
            "status": self.status
        }


@dataclass
class Stats:
    total_checks: int = 0
    tokens_saved: int = 0
    blocks: int = 0
    fallbacks: int = 0

    def to_dict(self) -> Dict[str, int]:
        return asdict(self)


class TokenEstimator:
    CJK_RANGES = [
        (0x4E00, 0x9FFF), (0x3400, 0x4DBF), (0x20000, 0x2A6DF),
        (0x2A700, 0x2B73F), (0x2B740, 0x2B81F), (0x2B820, 0x2CEAF),
        (0xF900, 0xFAFF), (0x2F800, 0x2FA1F), (0x3040, 0x309F),
        (0x30A0, 0x30FF), (0x31F0, 0x31FF), (0xAC00, 0xD7AF),
        (0x1100, 0x11FF), (0x3130, 0x318F), (0xA960, 0xA97F),
        (0xD7B0, 0xD7FF),
    ]

    @classmethod
    def is_cjk(cls, char: str) -> bool:
        if len(char) != 1:
            return False
        code = ord(char)
        for start, end in cls.CJK_RANGES:
            if start <= code <= end:
                return True
        return False

    @classmethod
    def estimate_tokens(cls, text: str) -> int:
        if not text:
            return 0
        cjk_count = 0
        ascii_count = 0
        other_count = 0
        for char in text:
            if cls.is_cjk(char):
                cjk_count += 1
            elif char.isalnum() or char.isspace():
                ascii_count += 1
            else:
                other_count += 1
        tokens = cjk_count + (ascii_count / 4) + (other_count / 2)
        return max(1, int(tokens)) if text.strip() else 0


class TokenGuard:
    def __init__(self, quotas: Optional[Dict[str, int]] = None):
        self.quotas = quotas.copy() if quotas else DEFAULT_QUOTAS.copy()
        self.usage: Dict[str, TokenUsage] = {}
        self.stats = Stats()
        self.retry_delays: Dict[str, float] = {}
        for model, tpm_limit in self.quotas.items():
            self.usage[model] = TokenUsage(model=model, tpm_limit=tpm_limit)

    def add_quota(self, model: str, tpm_limit: int) -> None:
        self.quotas[model] = tpm_limit
        if model not in self.usage:
            self.usage[model] = TokenUsage(model=model, tpm_limit=tpm_limit)
        else:
            self.usage[model].tpm_limit = tpm_limit

    def estimate_tokens(self, text: str) -> int:
        return TokenEstimator.estimate_tokens(text)

    def check_request(self, model: str, text: str, force: bool = False) -> Dict[str, Any]:
        self.stats.total_checks += 1
        if model not in self.usage:
            return {"allowed": False, "estimated_tokens": 0, "remaining": 0,
                    "status": "UNKNOWN", "message": f"Unknown model: {model}"}
        usage = self.usage[model]
        estimated_tokens = self.estimate_tokens(text)
        would_exceed = usage.used_this_minute + estimated_tokens > usage.tpm_limit
        usage_pct = usage.usage_pct
        if usage_pct >= THROTTLE_BLOCK_THRESHOLD and not force:
            self.stats.blocks += 1
            self.stats.tokens_saved += estimated_tokens
            return {"allowed": False, "estimated_tokens": estimated_tokens,
                    "remaining": usage.remaining, "status": "BLOCKED",
                    "message": f"Quota exhausted ({usage_pct:.1f}% used)"}
        if usage_pct >= THROTTLE_WARNING_THRESHOLD and not force:
            return {"allowed": True, "estimated_tokens": estimated_tokens,
                    "remaining": usage.remaining, "status": "THROTTLE",
                    "message": f"High usage ({usage_pct:.1f}%). Proceeding."}
        if would_exceed and not force:
            self.stats.tokens_saved += estimated_tokens
            return {"allowed": False, "estimated_tokens": estimated_tokens,
                    "remaining": usage.remaining, "status": "EXCEEDED",
                    "message": "Request would exceed quota"}
        return {"allowed": True, "estimated_tokens": estimated_tokens,
                "remaining": usage.remaining, "status": "OK", "message": "Request allowed"}

    def record_usage(self, model: str, tokens: int) -> Dict[str, Any]:
        if model not in self.usage:
            return {"success": False, "message": f"Unknown model: {model}"}
        self.usage[model].used_this_minute += tokens
        return {"success": True, "model": model, "tokens_recorded": tokens,
                "new_total": self.usage[model].used_this_minute,
                "remaining": self.usage[model].remaining}

    def record_429(self, model: str, retry_delay: Optional[float] = None,
                   error_response: Optional[str] = None) -> Dict[str, Any]:
        if retry_delay is None and error_response:
            retry_delay = self._parse_retry_delay(error_response)
        if retry_delay is None:
            retry_delay = 60.0
        if model in self.usage:
            self.retry_delays[model] = retry_delay
        return {"success": True, "model": model, "retry_delay": retry_delay,
                "message": f"Recorded 429 for {model}. Retry after {retry_delay}s"}

    def _parse_retry_delay(self, error_response: str) -> Optional[float]:
        try:
            data = json.loads(error_response)
            if isinstance(data, dict):
                if "retry_after" in data:
                    return float(data["retry_after"])
                if "error" in data and isinstance(data["error"], dict):
                    if "retry_after" in data["error"]:
                        return float(data["error"]["retry_after"])
                    msg = str(data["error"].get("message", ""))
                    match = re.search(r"(\\d+(?:\\.\\d+)?)\\s*seconds?", msg)
                    if match:
                        return float(match.group(1))
        except (json.JSONDecodeError, ValueError):
            pass
        match = re.search(r"Retry-After:\\s*(\\d+)", error_response, re.IGNORECASE)
        if match:
            return float(match.group(1))
        match = re.search(r"(\\d+(?:\\.\\d+)?)\\s*seconds?", error_response, re.IGNORECASE)
        if match:
            return float(match.group(1))
        return None

    def get_retry_delay(self, model: str) -> float:
        return self.retry_delays.get(model, 60.0)

    def get_status(self) -> Dict[str, Any]:
        return {
            "models": {m: u.to_dict() for m, u in self.usage.items()},
            "stats": self.stats.to_dict()
        }

    def reset_minute(self) -> Dict[str, Any]:
        for usage in self.usage.values():
            usage.used_this_minute = 0
        return {"success": True, "message": "Reset all usage counters"}


def main():
    parser = argparse.ArgumentParser(
        description="TokenGuard - LLM API 429 Prevention Engine",
        formatter_class=argparse.RawDescriptionHelpFormatter
    )
    subparsers = parser.add_subparsers(dest="command", help="Commands")

    # check command
    check_parser = subparsers.add_parser("check", help="Check if request is allowed")
    check_parser.add_argument("--model", "-m", required=True, help="Model name")
    check_parser.add_argument("--text", "-t", required=True, help="Request text")
    check_parser.add_argument("--force", "-f", action="store_true", help="Force check")
    check_parser.add_argument("--json", action="store_true", help="Output JSON")

    # record command
    record_parser = subparsers.add_parser("record", help="Record token usage")
    record_parser.add_argument("--model", "-m", required=True, help="Model name")
    record_parser.add_argument("--tokens", "-n", type=int, required=True, help="Tokens used")
    record_parser.add_argument("--json", action="store_true", help="Output JSON")

    # 429 command
    r429_parser = subparsers.add_parser("429", help="Record 429 event")
    r429_parser.add_argument("--model", "-m", required=True, help="Model name")
    r429_parser.add_argument("--delay", "-d", type=float, help="Retry delay in seconds")
    r429_parser.add_argument("--error", "-e", help="Error response text")
    r429_parser.add_argument("--json", action="store_true", help="Output JSON")

    # status command
    status_parser = subparsers.add_parser("status", help="Show status summary")
    status_parser.add_argument("--json", action="store_true", help="Output JSON")
    status_parser.add_argument("--output", "-o", help="Output file")

    # quota command
    quota_parser = subparsers.add_parser("quota", help="Manage quotas")
    quota_parser.add_argument("--model", "-m", help="Model name")
    quota_parser.add_argument("--limit", "-l", type=int, help="TPM limit")
    quota_parser.add_argument("--list", action="store_true", help="List all quotas")
    quota_parser.add_argument("--json", action="store_true", help="Output JSON")

    args = parser.parse_args()
    guard = TokenGuard()

    if args.command == "check":
        result = guard.check_request(args.model, args.text, args.force)
        if args.json:
            print(json.dumps(result, indent=2))
        else:
            print(f"Model: {args.model}")
            print(f"Estimated tokens: {result[\"estimated_tokens\"]}")
            print(f"Remaining: {result[\"remaining\"]}")
            print(f"Status: {result[\"status\"]}")
            print(f"Message: {result[\"message\"]}")

    elif args.command == "record":
        result = guard.record_usage(args.model, args.tokens)
        if args.json:
            print(json.dumps(result, indent=2))
        else:
            print(f"Recorded {args.tokens} tokens for {args.model}")
            print(f"New total: {result.get(\"new_total\", 0)}")
            print(f"Remaining: {result.get(\"remaining\", 0)}")

    elif args.command == "429":
        result = guard.record_429(args.model, args.delay, args.error)
        if args.json:
            print(json.dumps(result, indent=2))
        else:
            print(f"Recorded 429 for {args.model}")
            print(f"Retry after: {result[\"retry_delay\"]}s")

    elif args.command == "status":
        status = guard.get_status()
        if args.json:
            output = json.dumps(status, indent=2)
            if args.output:
                with open(args.output, "w") as f:
                    f.write(output)
            else:
                print(output)
        else:
            print("TokenGuard Status")
            print("=" * 40)
            for model, data in status["models"].items():
                print(f"{model}: {data[\"status\"]} ({data[\"usage_pct\"]})")
            print(f"\nStats: {status[\"stats\"]}")

